// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract RevertingReceiver {
    receive() external payable { revert("reject"); }
    fallback() external payable { revert("reject"); }
}

contract InvMutTest is Test {
    SimpleWallet c;
    RevertingReceiver rr;

    function setUp() public {
        c = new SimpleWallet();
        rr = new RevertingReceiver();
    }

    function testFuzz_failedForwardMustRevert(uint96 amount) public {
        uint256 value = bound(uint256(amount), 1, 100 ether);
        vm.deal(address(c), value);
        vm.expectRevert();
        c.sendMoney(address(rr), value, "");
    }
}
